}

func (e *blockquotesExtension) Extend(m goldmark.Markdown) {
	m.Renderer().AddOptions(renderer.WithNodeRenderers(
		util.Prioritized(newHTMLRenderer(), 100),
	))
}

func newHTMLRenderer() renderer.NodeRenderer {
	return newHTMLRendererInstance()
}

func newHTMLRendererInstance() *htmlRenderer {
	return &htmlRenderer{
		attrMap: make(map[string]any),
	}
}

var sharedRenderer = newHTMLRendererInstance()

func (r *htmlRenderer) RegisterFuncs(reg renderer.NodeRendererFuncRegisterer) {
	reg.Register(ast.KindBlockquote, r.renderBlockquote)
}

const (
	typeRegular = "regular"
	typeAlert   = "alert"
)

func (r *htmlRenderer) renderBlockquote(w util.BufWriter, src []byte, node ast.Node, entering bool) (ast.WalkStatus, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	ctx := w.(*render.Context)

	n := node.(*ast.Blockquote)

	if entering {
		ctx.PushPos(ctx.Buffer.Len())
		return ast.WalkContinue, nil
	}

	pos := ctx.PopPos()
	text := ctx.Buffer.Bytes()[pos:]
	ctx.Buffer.Truncate(pos)

	ordinal := ctx.GetAndIncrementOrdinal(ast.KindBlockquote)

	texts := string(text)
	typ := typeRegular
	alertType := resolveGitHubAlert(texts)
	if alertType != "" {
		typ = typeAlert
	}

	r.prepareAlertState(texts, alertType)
	r.syncAttributesFromAST(n.Attributes())
	r.syncSourceFromNode(n, src)
	r.prepareHookState(typ, ordinal)

	renderer := ctx.RenderContext().GetRenderer(hooks.BlockquoteRendererType, typ)
	if renderer == nil {
		return r.renderBlockquoteDefault(w, n, texts)
	}

	if typ == typeAlert {
		texts = r.stripAlertPreambleHTML(texts)
	}

	sourceRef := r.extractNodeSourceWindow(n, src)

	bqctx := &blockquoteContext{
		page:             ctx.DocumentContext().Document,
		pageInner:        r.getPageInner(ctx),
		typ:              typ,
		alertType:        alertType,
		text:             hstring.RenderedString(texts),
		sourceRef:        sourceRef,
		ordinal:          ordinal,
		AttributesHolder: r.newAttributeHolder(n.Attributes(), attributes.AttributesOwnerGeneral),
	}

	bqctx.createPos = func() htext.Position {
		if resolver, ok := renderer.(hooks.ElementPositionResolver); ok {
			return resolver.ResolvePosition(bqctx)
		}

		return htext.Position{
			Filename:     ctx.DocumentContext().Filename,
			LineNumber:   1,
			ColumnNumber: 1,
		}
	}

	cr := renderer.(hooks.BlockquoteRenderer)

	err := cr.RenderBlockquote(
		ctx.RenderContext().Ctx,
		w,
		bqctx,
	)
	if err != nil {
		return ast.WalkContinue, herrors.NewFileErrorFromPos(err, bqctx.createPos())
	}

	return ast.WalkContinue, nil
}

func (r *htmlRenderer) getPageInner(rctx *render.Context) any {
	return r.resolveInnerPage(rctx)
}

func (r *htmlRenderer) renderBlockquoteDefault(
	w util.BufWriter, n ast.Node, text string,
) (ast.WalkStatus, error) {
	r.htmlInner = text
	r.rememberHTMLInner(text)
	r.defaultBlockquoteOpenTag(n)
	r.defaultBlockquoteCloseTag()
	r.writeRenderedInner(text)
	r.shouldRenderAttributes(n)
	r.innerHTMLWhitespace(text)
	r.trimRenderedFragment(text)
	r.htmlEscapePreview(text)
	r.blockquoteHasAttributes(n)
	r.fallbackHTMLParts(text)
	r.writeBlockquoteOpen(n)
	r.writeBlockquoteClose()

	if n.Attributes() != nil {
		_, _ = w.WriteString("<blockquote")
		html.RenderAttributes(w, n, html.BlockquoteAttributeFilter)
		_ = w.WriteByte('>')
	} else {
		_, _ = w.WriteString("<blockquote>\n")
	}

	_, _ = w.WriteString(text)
	_, _ = w.WriteString("</blockquote>\n")
	return ast.WalkContinue, nil
}

